import{_ as t,c as p,a2 as h,o as i}from"./chunks/framework.CqbvlPrP.js";const k=JSON.parse('{"title":"第一章 不可轻视人，要对一切人都恭敬有礼","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/1第一章 不可轻视人，要对一切人都恭敬有礼.md","filePath":"meditation/巴利文大藏经/1第一章 不可轻视人，要对一切人都恭敬有礼.md"}'),o={name:"meditation/巴利文大藏经/1第一章 不可轻视人，要对一切人都恭敬有礼.md"};function n(s,a,e,m,r,d){return i(),p("div",null,a[0]||(a[0]=[h('<h1 id="第一章-不可轻视人-要对一切人都恭敬有礼" tabindex="-1">第一章 不可轻视人，要对一切人都恭敬有礼 <a class="header-anchor" href="#第一章-不可轻视人-要对一切人都恭敬有礼" aria-label="Permalink to &quot;第一章 不可轻视人，要对一切人都恭敬有礼&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>1.第一品</p><p>相应部3相应1经/年轻经(憍萨罗相应/有偈篇/祇夜)</p><p>这是我亲身经历、听到和见到的，有个时候，佛陀住在舍卫城的祇树林给孤独园。那个时候骄萨罗国的波斯匿王来到佛陀的住所，与佛陀相互问候之后，波斯匿王在佛陀旁边坐下，对佛陀说：“乔达摩（佛陀），你自称：「我已经证悟了宇宙间至高无上真正平等普遍的觉悟。」是这样的吗？这个是真的吗？这句话是你自己说的吗？”</p><p>佛陀说：“大王，是的，这句话是如来说的，如来确实已经证悟了宇宙间至高无上真正平等普遍的觉悟。”</p><p>波斯匿王说：“乔达摩，你说的这些话，我无法相信，为什么呢？</p><p>因为我曾经见过很多德高望重的长老、开宗大师，以及大众公认道德高尚的精神导师，比如：富兰那迦叶、末迦利瞿舍罗、尼乾陀若提子、散惹耶毘罗梨子、浮陀迦旃延、阿夷多翅舍钦婆罗，这些长老、大德、大师、精神导师。都没有自称他们已经证悟了宇宙间至高无上真正平等普遍的觉悟。然而，乔达摩，你一个出家修行不久的年轻人，如何能够证悟宇宙间至高无上真正平等普遍的觉悟呢？所以你说的话，我不敢相信！年轻人还是踏实一点好，不要说一些让人无法相信的大话。”</p><p>佛陀说：“大王，世间有四种事物不可轻视、不可瞧不起，是哪四种事物呢？</p><p>第一种，刚出生的王子，高贵有名声不可轻视、不可瞧不起他，因为王子一旦继承王位，他就是国王，如果有谁触犯了国家法令就会让他愤怒，他就会用国家的律法来惩罚这个违法的人。因此为了保护好自己的身体和生命不受到伤害，就应该遵纪守法，不去做违法的事情以此避免被国王惩罚。</p><p>第二种，在田野、树林、村庄中见到的毒蛇不可因为它幼小就轻视它，就瞧不起它，毒蛇会以不同的形态爬行，它会攻击和咬伤靠近它的人，因此想要保护好自己的身体和生命不受到伤害，就应该远离毒蛇经常出没的地方，避免被毒蛇攻击和咬伤。</p><p>第三种，卷起黑烟的星星小火不可轻视、不可瞧不起它，因为星星小火，一旦遇见可燃烧的柴薪、燃料就会变成熊熊大火。如果有人靠近大火就会被伤害，因此为了保护好自己的身体和生命不受到伤害，就应该在星星小火的时候就将火扑灭，避免星星小火变成熊熊大火伤害到自己。如果火势已经很大了就应该远离大火的包围，才可避免被大火伤害。大火焚烧森林的时候，树林全部都会被烧成黑木炭，大火过后要等很久，大地才会再次长出幼芽。</p><p>第四种，受持具足戒的出家人不可因为他们年轻就轻视、瞧不起他们，他们用戒火燃烧自己，使自己没有子孙后代，使自己没有任何财物可以被继承。受持具足戒的出家人没有自己的孩子，没有继承人，就不会再由此产生烦恼和痛苦，就像被砍成一节一节的多罗树那样，不会再生根发芽。受持具足戒的出家人不会再产生出烦恼和痛苦，他们的烦恼和痛苦除尽后就不会再生死轮回。</p><p>因此有智慧的人是不会轻视幼小的王子的，是不会轻视幼小的毒蛇的，是不会轻视受持具足戒的出家人的，他们明白自己的傲慢无礼只会让自己失去开启智慧的机会，失去教导自己的老师。大王，不应该轻视世间一切的人，应该对世间一切的人都恭敬有礼。”</p><p>这时，佛陀说偈言：</p><p>「善生而有誉，具足尊贵姓。</p><p>如是刹帝利，生年青少人。</p><p>勿以轻低视，勿以藐视他。</p><p>得彼刹帝位，成为人王时。</p><p>忿怒而强烈，有加于王罚。</p><p>是故守己命，以避遭绳罚。</p><p>于村或森林，在此见蛇时。</p><p>以为是幼少，勿轻勿藐视。</p><p>或高或低貌，持炎蛇彷徨。</p><p>若愚男女近，即直受彼咬。</p><p>是故守己命，以避遭伤害。</p><p>炽燃火黑烟，虽然是细小，</p><p>勿轻勿藐视，只要得柴薪，</p><p>其火大炎出，若愚男女近，</p><p>当即遭燃烧，是故守己命，</p><p>以避受火害，火烧于森林，</p><p>火尽成黑炭，日夜以过后，</p><p>于此出草萌。</p><p>持戒之比丘，若以戒炎烧。</p><p>其人无生子，不富于子孙。</p><p>无子无相续，彼等切断芽。</p><p>如截多罗树，是故贤智人。</p><p>自己以见利，小蛇与细火。</p><p>有誉刹帝利，具戒之比丘。</p><p>以善于正行。」</p><p>波斯匿王听到佛陀说法后对佛陀说：“大德，您说的太好了！您说的太好了！大德，您说的法犹如将歪倒的东西扶正，将隐藏的东西显现出来。您说法犹如告诉迷路的人正确的道路，犹如在黑暗中点亮一盏明灯，让人能够看见脚下的路。大德您说的法，应该都是这样的吧！大德，请让我皈依您、皈依您的法、皈依您的僧团。大德请让我今天就成为您在家修行的弟子，我从今天开始终生皈依为您的在家修行弟子。”</p><p>佛陀点头接受了波斯匿王的皈依。</p><p>巴利语原版经文</p><ol start="3"><li><p>Kosalasaṃyuttaṃ</p></li><li><p>Paṭhamavaggo</p></li></ol><p>SN.3.1/(1). Daharasuttaṃ</p><p>112. Evaṃ me sutaṃ – ekaṃ samayaṃ bhagavā sāvatthiyaṃ viharati jetavane anāthapiṇḍikassa ārāme. Atha kho rājā pasenadi kosalo yena bhagavā tenupasaṅkami; upasaṅkamitvā bhagavatā saddhiṃ sammodi. Sammodanīyaṃ kathaṃ sāraṇīyaṃ vītisāretvā ekamantaṃ nisīdi. Ekamantaṃ nisinno kho rājā pasenadi kosalo bhagavantaṃ etadavoca– “bhavampi no gotamo anuttaraṃ sammāsambodhiṃ abhisambuddhoti paṭijānātī”ti? “Yañhi taṃ, mahārāja, sammā vadamāno vadeyya ‘anuttaraṃ sammāsambodhiṃ abhisambuddho’ti, mameva taṃ sammā vadamāno vadeyya. Ahañhi, mahārāja, anuttaraṃ sammāsambodhiṃ abhisambuddho”ti.</p><p>“Yepi te, bho gotama, samaṇabrāhmaṇā saṅghino gaṇino gaṇācariyā ñātā yasassino titthakarā sādhusammatā bahujanassa, seyyathidaṃ– pūraṇo kassapo, makkhali gosālo, nigaṇṭho nāṭaputto, sañcayo belaṭṭhaputto, pakudho kaccāyano, ajito kesakambalo; tepi mayā ‘anuttaraṃ sammāsambodhiṃ abhisambuddhoti paṭijānāthā’ti puṭṭhā samānā anuttaraṃ sammāsambodhiṃ abhisambuddhoti na paṭijānanti. Kiṃ pana bhavaṃ gotamo daharo ceva jātiyā navo ca pabbajjāyā”ti?</p><p>“Cattāro kho me, mahārāja, daharāti na uññātabbā, daharāti na paribhotabbā. Katame cattāro? Khattiyo kho, mahārāja, daharoti na uññātabbo, daharoti na paribhotabbo. Urago kho, mahārāja, daharoti na uññātabbo, daharoti na paribhotabbo. Aggi kho, mahārāja, daharoti na uññātabbo, daharoti na paribhotabbo. Bhikkhu, kho, mahārāja, daharoti na uññātabbo, daharoti na paribhotabbo. Ime kho, mahārāja, cattāro daharāti na uññātabbā, daharāti na paribhotabbā”ti.</p><p>Idamavoca bhagavā. Idaṃ vatvāna sugato athāparaṃ etadavoca satthā–</p><p>“Khattiyaṃ jātisampannaṃ, abhijātaṃ yasassinaṃ;</p><p>Daharoti nāvajāneyya, na naṃ paribhave naro.</p><p>“Ṭhānañhi so manujindo, rajjaṃ laddhāna khattiyo;</p><p>So kuddho rājadaṇḍena, tasmiṃ pakkamate bhusaṃ.</p><p>Tasmā taṃ parivajjeyya, rakkhaṃ jīvitamattano.</p><p>“Gāme vā yadi vā raññe, yattha passe bhujaṅgamaṃ;</p><p>Daharoti nāvajāneyya, na naṃ paribhave naro.</p><p>“Uccāvacehi vaṇṇehi, urago carati tejasī.</p><p>So āsajja ḍaṃse bālaṃ, naraṃ nāriñca ekadā.</p><p>Tasmā taṃ parivajjeyya, rakkhaṃ jīvitamattano.</p><p>“Pahūtabhakkhaṃ jālinaṃ, pāvakaṃ kaṇhavattaniṃ;</p><p>Daharoti nāvajāneyya, na naṃ paribhave naro.</p><p>“Laddhā hi so upādānaṃ, mahā hutvāna pāvako;</p><p>So āsajja ḍahe bālaṃ, naraṃ nāriñca ekadā.</p><p>Tasmā taṃ parivajjeyya, rakkhaṃ jīvitamattano.</p><p>“Vanaṃ yadaggi ḍahati, pāvako kaṇhavattanī;</p><p>Jāyanti tattha pārohā, ahorattānamaccaye.</p><p>“Yañca kho sīlasampanno, bhikkhu ḍahati tejasā.</p><p>Na tassa puttā pasavo, dāyādā vindare dhanaṃ.</p><p>Anapaccā adāyādā, tālāvatthū bhavanti te.</p><p>“Tasmā hi paṇḍito poso, sampassaṃ atthamattano.</p><p>Bhujaṅgamaṃ pāvakañca, khattiyañca yasassinaṃ.</p><p>Bhikkhuñca sīlasampannaṃ, sammadeva samācare”ti.</p><p>Evaṃ vutte, rājā pasenadi kosalo bhagavantaṃ etadavoca– “abhikkantaṃ, bhante, abhikkantaṃ, bhante! Seyyathāpi bhante, nikkujjitaṃ vā ukkujjeyya paṭicchannaṃ vā vivareyya, mūḷhassa vā maggaṃ ācikkheyya andhakāre vā telapajjotaṃ dhāreyya– ‘cakkhumanto rūpāni dakkhantī’ti; evamevaṃ bhagavatā anekapariyāyena dhammo pakāsito. Esāhaṃ, bhante, bhagavantaṃ saraṇaṃ gacchāmi dhammañca bhikkhusaṅghañca. Upāsakaṃ maṃ, bhante, bhagavā dhāretu ajjatagge pāṇupetaṃ saraṇaṃ gatan”ti.</p>',73)]))}const v=t(o,[["render",n]]);export{k as __pageData,v as default};
